        assert.equal(mod2().safeSha('facade1'), 'facade1');
        assert.equal(mod2().safeSha('facad'), null, 'shorter than 7');
        assert.equal(mod2().safeSha('main'), null);
        assert.equal(mod2().safeSha(null), null);
        assert.equal(mod2().safeTestPath('testing/tests/TS-7/test.py'), 'testing/tests/TS-7/test.py');
        assert.equal(mod2().safeTestPath('-v'), null);
        assert.equal(mod2().safeTestPath('a b/test.py'), null);
        assert.equal(mod2().safeTestPath('a;id/test.py'), null);
        assert.equal(mod2().safeTestPath('../x.py'), null);
        assert.equal(mod2().safeTestPath(null), null);
    });
});

