function numericKey(key) {
    var m = /(\d+)\s*$/.exec(String(key || ''));
    return m ? parseInt(m[1], 10) : Number.MAX_SAFE_INTEGER;
}

function descriptionOf(tc) {
    return (tc && tc.fields && tc.fields.description) || (tc && tc.description) || '';
}

function tcKeyOf(tc) {
    return String((tc && tc.key) || '');
}

/** True when a linked TC already carries a `Verifies: <bugKey>` oracle stamp. */
function hasOracleStamp(list, bugKey) {
    var target = String(bugKey || '').toLowerCase();
    var matches = list.filter(function(tc) {
        var marker = parseRoleMarker(descriptionOf(tc));
        return !!marker && marker.kind === 'verifies' &&
            String(marker.key).toLowerCase() === target;
    });
    return matches.length > 0;
}

/** The unmarked linked TCs, oracle-election order: lowest key first. */
function unmarkedSorted(list) {
    var unmarked = list.filter(function(tc) { return !parseRoleMarker(descriptionOf(tc)); });
    unmarked.sort(function(a, b) {
        var d = numericKey(tcKeyOf(a)) - numericKey(tcKeyOf(b));
        return d !== 0 ? d : (tcKeyOf(a) < tcKeyOf(b) ? -1 : 1);
    });
    return unmarked;
}

/** The stamp for one unmarked TC: the first elects the oracle, the rest guard. */
function stampFor(isOracle, bugKey, scope) {
    return isOracle ? (VERIFIES_PREFIX + ' + bugKey) : (GUARD_PREFIX + ' + scope);
}

/**
 * The plan for the unmarked TCs in election order: the first unmarked TC
 * becomes the oracle unless one already exists, every other one a guard.
 */
function planUnmarked(unmarked, oracleExists, bugKey, scope) {
    var plan = [];
    var oracleTaken = oracleExists;
    unmarked.forEach(function(tc) {
        var isOracle = !oracleTaken;
        oracleTaken = true;
        plan.push({ tcKey: tcKeyOf(tc), marker: stampFor(isOracle, bugKey, scope) });
    });
    return plan;
}

/**
 * The mechanical stamp plan for a set of linked TCs of one bug.
 * Returns [{ tcKey, marker }] for exactly the TCs that need a stamp.
 *
 * Rules (see the module header): already-marked TCs are skipped; an existing
 * oracle marking THIS bug suppresses the oracle election; otherwise the
 * lowest-key unmarked TC becomes the oracle and the rest become guards with
 * the bug summary as scope (falling back to the bug key).
 */
function stampPlan(tcs, bugKey, bugSummary) {
    var list = Array.isArray(tcs) ? tcs : [];
    var scope = String(bugSummary || '').trim() || String(bugKey || '');
    return planUnmarked(unmarkedSorted(list), hasOracleStamp(list, bugKey), bugKey, scope);
}

